def rule(id,when,typ,message,page='3',supplement=False,priority=70):
 rules.append(dict(id=id,priority=priority,when=when,action=dict(type=typ,components=['tepotinib'],message=message,dose_calculation='specialist_review'),source=src(page,supplement),explanation=message))
rule('ECOG_OUTSIDE_USUAL_RANGE',test('ecog','>',2),'consultant_review','NCCP eligibility is ECOG 0–2. Outside that range, review suitability with the Consultant.','1')
