rule('INDICATION_OUTSIDE_SCOPE',b('indication_id','outside_scope'),'consultant_review','This suite covers NCCP 00823a only: advanced METex14 NSCLC after immunotherapy and/or platinum chemotherapy. Do not extend first-line trial results into this indication.','1')
rule('MET_NOT_CONFIRMED',b('met_ex14_validated',False),'consultant_review','A validated positive MET exon 14 skipping test is required before tepotinib.','1')
rule('PRIOR_THERAPY_NOT_MET',b('prior_immunotherapy_or_platinum',False),'consultant_review','Prior immunotherapy and/or platinum-based chemotherapy is part of NCCP 00823a and the EU indication. Review the proposed setting.','1')
