rule('PREGNANCY_BREASTFEEDING',anyof(b('pregnancy'),b('breastfeeding')),'contraindicated','Pregnancy and breastfeeding are NCCP exclusions. Refer promptly for an authorised specialist plan.','2',priority=98)
rule('ACTIVE_CNS_METASTASES',b('active_cns_metastases'),'contraindicated','Active CNS metastases are excluded by NCCP 00823 v2. Distinguish active from neurologically stable disease; review the treatment plan.','2',priority=98)
rule('ILD_SUSPECTED',anyof(b('ild_suspected'),test('pneumonitis_grade','>',0)),'withhold','Withhold tepotinib for suspected ILD/pneumonitis of any grade and promptly investigate. A grade or symptom alone does not confirm the diagnosis.',priority=85)
rule('ILD_CONFIRMED',b('ild_confirmed'),'permanently_discontinue','Permanently discontinue tepotinib if ILD is confirmed, at any grade.',priority=100)
