rule('LFT_COMBINED_CAUSE_UNRESOLVED',allof(combined,anyof(b('cholestasis_or_haemolysis_absent',False),missing('cholestasis_or_haemolysis_absent'))),'withhold','Withhold and urgently review ALT/AST >3 ×ULN plus bilirubin >2 ×ULN. The source permanent-stop pathway requires absence of cholestasis and haemolysis; establish the cause before assigning that pathway.',priority=85)
