rule('OTHER_RECOVERY_REVIEW',allof(b('other_toxicity_held'),b('other_toxicity_recovered_le2')),'consultant_review','Recovery to grade ≤2 permits reassessment of the interrupted plan. The source does not specify automatic re-escalation from 225 mg to 450 mg; the Consultant authorises the next dose.')
rule('QTC_RISK_REVIEW',b('qtc_risk_or_prolongation'),'consultant_review','Review QTc risk, concomitant medicines and electrolytes; obtain ECG/electrolyte monitoring as clinically indicated. NCCP and SmPC do not give a tepotinib-specific numeric QTc dose-change rule.','1–2; EMA section 4.4')
for f,id,msg in [('pgp_narrow_therapeutic_index_substrate','PGP_INTERACTION','Tepotinib inhibits P-gp. Review sensitive narrow-therapeutic-index substrates such as dabigatran or digoxin; concomitant drug adjustment and monitoring may be needed.'),('sensitive_bcrp_substrate','BCRP_INTERACTION','Monitor adverse effects of sensitive BCRP substrates such as rosuvastatin, methotrexate or topotecan during co-administration.'),('metformin_use','METFORMIN_INTERACTION','Monitor metformin clinical effects during tepotinib treatment because of potential OCT/MATE transporter interaction.')]:rule(id,b(f),'consultant_review',msg,'5–6 / section 4.5',True)
