sources=[dict(id='nccp',title='NCCP 00823 v2 tepotinib therapy (12/09/2025)',url=NCCP),dict(id='smpc',title='EMA Tepmetko product information, updated 08/10/2026',url=SMPC),dict(id='vision',title='VISION long-term follow-up, Mazieres et al., JAMA Oncology 2023',url=VISION),dict(id='vision-2025',title='VISION treatment sequencing: ≥3-year follow-up, ESMO 2025 abstract 1995P',url=LONG),dict(id='vision-2026',title='VISION sustained-response subset, ASCO 2026 abstract 8612',url=SUBSET),dict(id='antiemetic',title='NCCP SACT Antiemetic Guidance V6 (2025), oral therapy Table 5',url=ANTI),dict(id='ncis',title='NCCP NCIS supportive antiemetics V8: parenteral guidance',url=NCIS)]
scope='NCCP 00823a covers tepotinib on its own for adults with advanced non-small cell lung cancer carrying a confirmed MET exon 14 skipping change, after immunotherapy and/or platinum chemotherapy. It is not a first-line or adjuvant treatment guide.'
schedule='The usual starting dose is 450 mg once daily: two 225 mg tablets taken together with food. Treatment is continuous, without a planned rest week, while it is helping. Follow your prescribed dose; the team may use one 225 mg tablet or pause treatment for side effects.'
administration='Take at the same time each day with food and swallow whole. If a dose is missed, take it when remembered on the same day unless the next dose is due within 8 hours; then skip it. Do not double a dose. Ask your pharmacist if the timing is uncertain or if you vomit; do not take a replacement without advice. If swallowing is difficult, ask about the approved water-dispersion method.'
purpose='Tepotinib blocks the MET growth signal in selected lung cancers with a MET exon 14 skipping change. In advanced cancer the aim is to control the cancer and its symptoms. The tumour test and previous treatment help determine whether it is suitable.'
baseline='Confirm the MET result, previous treatment, dose, other medicines and emergency contact. Check blood count, electrolytes, kidney and liver function; ECG if clinically indicated. Discuss pregnancy, contraception and breastfeeding, and perform a pregnancy test when applicable.'
ongoing='Repeat blood count, electrolytes, kidney and liver tests at the team’s agreed reviews. ECG is used when clinically indicated. Report new lung symptoms, swelling, diarrhoea or vomiting between visits. A rise in creatinine needs assessment because the medicine can change the test result without necessarily damaging the kidneys. Scans follow the Consultant’s plan.'
urgent='Contact the oncology team urgently for new or worsening cough, breathlessness or fever; marked swelling or sudden weight gain; severe diarrhoea, repeated vomiting or inability to drink; yellow skin or eyes, dark urine or severe abdominal pain; or palpitations or fainting. Severe breathing difficulty, collapse or swelling of the mouth or throat needs emergency help. Use your unit’s temperature and 24-hour contact instructions.'
repro='Avoid pregnancy during treatment. Effective contraception is needed during treatment and for at least one week after the last dose; women using hormonal contraception should also use a barrier method. Men with a partner who could become pregnant should use barrier contraception for the same period. Do not breastfeed during treatment or for at least one week afterwards. Human fertility effects are not known; discuss fertility before starting.'
interaction='Ask the pharmacist to check all prescribed medicines, non-prescription medicines and supplements before changes. Tepotinib can affect medicines including dabigatran, digoxin, rosuvastatin and metformin. Supportive medicines may also affect heart rhythm; individual advice is needed.'
support=[dict(title='Swelling and weight changes',text='Report swelling early and discuss changes in weight, movement or breathing. The team will assess the cause and agree treatment; do not start a water tablet or change tepotinib yourself.',source_ids=['smpc']),dict(title='Diarrhoea and fluids',text='Agree a diarrhoea treatment plan before starting. Begin the prescribed anti-diarrhoeal medicine at the first loose stool as instructed, and maintain fluids if able. Persistent diarrhoea, weakness or reduced urine needs prompt advice.',source_ids=['nccp','smpc']),dict(title='Nausea medicines',text='Tepotinib has minimal-to-low oral emetic risk. Agree an as-needed anti-sickness plan with the team, including medicine-interaction and heart-rhythm checks; no routine infusion premedication is specified.',source_ids=['nccp','antiemetic']),dict(title='Medicine review',text=interaction,source_ids=['smpc']),dict(title='Pregnancy, fertility and breastfeeding',text=repro,source_ids=['nccp','smpc'])]
evidence_plain='VISION found that tepotinib could shrink some advanced MET exon 14 skipping lung cancers, including cancers previously treated with other medicines. It was a single-arm study, so it does not show how much longer people live compared with another treatment. Study results describe groups and cannot predict your own outcome.'
stages=['Before the first dose','Starting daily treatment','Ongoing reviews','Benefit or toxicity review','Change or stopping']
