clinical=dict(component_rationale='Tepotinib inhibits MET signalling in METex14-skipping NSCLC. This is monotherapy after immunotherapy and/or platinum chemotherapy; no cytotoxic component or fixed number of cycles is added.',key_points=[scope,'Usual starting dose 450 mg active tepotinib (two 225 mg tablets) daily with food; VISION 500 mg is the salt dose, corresponding to 450 mg active moiety.','Keep suspected and confirmed ILD distinct at every grade.','Retain bilirubin and cholestasis/haemolysis qualifiers for liver discontinuation and the seven-day recovery-to-baseline distinction.','Renal impairment below CrCl 30 mL/min / dialysis requires explicit reconciliation of NCCP and current SmPC.','Other grade ≥3 adverse reactions use the 225 mg pathway or a considered interruption no longer than 21 days; no automatic repeat halving or re-escalation.'],patient_selection=dict(disease_and_biomarker_context=['NCCP 00823a: adults with advanced NSCLC, validated MET exon 14 skipping alteration, after immunotherapy and/or platinum chemotherapy.','No activating EGFR mutation or ALK rearrangement; NCCP ECOG 0–2. VISION largely enrolled ECOG 0–1, limiting direct extrapolation to ECOG 2.'],fitness_and_organ_function=['Assess renal/hepatic function, respiratory history, oedema, nutrition and functional status.','Child–Pugh C is not recommended. CrCl <30 / dialysis requires resolving the source discrepancy before a dose decision.'],exclusions_and_cautions=['NCCP exclusions: hypersensitivity, active CNS metastases, pregnancy or breastfeeding.','ILD and QTc risk are explicit cautions; clinically stable CNS disease must not be equated with active CNS disease.'],shared_decision_points=['Discuss single-arm efficacy evidence and alternatives; no comparative survival benefit is established.','Agree monitoring, medicine supply, adherence, side-effect support and contact plan.']),support_summary='Minimal-to-low oral emetic risk; individual as-needed antiemetics under local policy, no specified routine premedication. NCCP lists loperamide 4 mg at first loose stool then 2 mg after each loose stool (maximum 16 mg/day), or local policy; check the individual prescription and escalation plan. Review interactions and QT risk when selecting supportive medicines.',baseline=[baseline],before_each_cycle=['No chemotherapy cycle is defined. At scheduled reviews check FBC, electrolytes, renal/liver profile, symptoms, weight/oedema, adherence and medicines.'],ongoing=[ongoing,'Liver enzymes and bilirubin before starting and thereafter as clinically indicated; no invented monthly or two-weekly cadence.','Pregnancy testing during treatment if clinically indicated.'],administration=[administration,'Usual dose 450 mg active tepotinib daily. Source reduction level 225 mg daily; all modifications discussed with Consultant.','For inability to swallow: SmPC permits dispersion in 30 mL non-carbonated water without crushing, administration within one hour, and a 30 mL rinse; tube administration has separate instructions and requires pharmacy supervision.'],access='Oral medicine; no infusion access or ambulatory pump is intrinsic to this regimen. Tests, scans and clinical reviews still require a planned service.',drug_mechanisms={'tepotinib':'Reversible ATP-competitive MET tyrosine kinase inhibitor; suppresses MET phosphorylation and downstream PI3K/Akt and MAPK/ERK signalling in tumours with activating MET alterations.'},rationale=dict(summary='Biomarker-directed monotherapy for advanced METex14-skipping NSCLC after prior immunotherapy and/or platinum chemotherapy, supported by the nonrandomised VISION cohorts.',benefit_and_uncertainty=[evidence_plain],limitations=['No randomised comparator in VISION; objective response and duration of response do not prove an overall-survival advantage.','Do not substitute treatment-naive, Asian-only or long-responder selected-subset outcomes for the entire previously treated population.','Current NCCP operational eligibility and EU indication take precedence over broader trial recruitment.'],sources=[dict(label='EMA Tepmetko product information',url=SMPC),dict(label='VISION long-term follow-up',url=VISION)]))
